import React, { useImperativeHandle, useRef } from 'react';

import * as AlertDialog from '@radix-ui/react-alert-dialog';
import { omitTransientProps } from 'utils/emotion';

import {
  StyledCriticalLine,
  StyledDialogActions,
  StyledDialogBody,
  StyledDialogHeader,
  StyledDialogTitle,
  StyledModalContent,
  StyledOverlay,
} from '../Modal.styles';
import type { ModalRootProps } from '../Modal.types';

export const ModalRoot = React.forwardRef<HTMLDivElement, ModalRootProps>(
  (
    {
      children,
      variant = 'overlay',
      destructive = 'off',
      onEscapeKeyDown,
      headerImage,
      headerHeight,
      title,
      actions,
      trigger,
      ...props
    },
    forwardedRef,
  ) => {
    const innerRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(forwardedRef, () => innerRef.current as HTMLDivElement);

    const hasHeader = Boolean(headerImage || title);

    return (
      <AlertDialog.Root {...omitTransientProps(props)}>
        {trigger ? (
          <AlertDialog.Trigger asChild>{trigger}</AlertDialog.Trigger>
        ) : null}
        <StyledOverlay />
        <StyledModalContent
          ref={innerRef}
          $variant={variant}
          data-variant={variant}
          onEscapeKeyDown={onEscapeKeyDown}
        >
          {destructive === 'critical' ? (
            <StyledCriticalLine data-testid="destructive" />
          ) : null}
          {hasHeader ? (
            <StyledDialogHeader
              $hasImage={Boolean(headerImage)}
              $headerHeight={headerHeight}
            >
              {headerImage}
              {title ? (
                <StyledDialogTitle $shouldAdjustPadding={!headerImage}>
                  {title}
                </StyledDialogTitle>
              ) : null}
            </StyledDialogHeader>
          ) : null}
          <StyledDialogBody
            $adjustRightPadding={false}
            $adjustTopPadding={!headerImage && !title}
          >
            {children}
          </StyledDialogBody>
          {actions ? (
            <StyledDialogActions>{actions}</StyledDialogActions>
          ) : null}
        </StyledModalContent>
      </AlertDialog.Root>
    );
  },
);

ModalRoot.displayName = 'Modal.Root';
